L19_1.m_Talk_TWN = "\230\148\190\229\191\131\229\144\167\239\188\140\230\136\145\233\128\154\229\184\184\230\152\175\230\148\175\230\140\129\230\132\155\230\131\133\231\154\132\226\128\166\226\128\166"
L19_1.m_Talk_THA = "\224\185\128\224\184\155\224\184\165\224\185\136\224\184\178\224\184\153\224\184\176\224\184\132\224\184\176 \224\184\137\224\184\177\224\184\153\224\184\162\224\184\180\224\184\153\224\184\148\224\184\181\224\184\129\224\184\177\224\184\154\224\184\132\224\184\167\224\184\178\224\184\161\224\184\163\224\184\177\224\184\129\224\184\151\224\184\184\224\184\129\224\184\163\224\184\185\224\184\155\224\185\129\224\184\154\224\184\154"
