L19_1.m_Talk_SCN = "\228\184\141\230\152\175\231\154\132\227\128\130\230\136\145\232\191\153\228\184\170\228\186\186\230\148\175\230\140\129\229\164\167\233\131\168\229\136\134\231\154\132\231\136\177\230\131\133\226\128\166\226\128\166"
