L21_1.m_Talk_KOREA = "\236\160\156\234\176\128 \236\149\140\234\179\160 \236\158\136\235\138\148 <color=#ffd34c>\234\187\132\235\129\132\235\159\172\236\154\180 \235\185\132\235\176\128</color>\236\157\132 \234\179\160\234\176\157\235\139\152\234\187\152\236\132\156\235\143\132 \236\149\140\236\149\132\235\145\144\235\138\148 \237\142\184\236\157\180 \236\162\139\236\157\132 \234\178\131 \234\176\153\236\149\132\236\132\156\236\154\148."
L21_1.m_fTalkTime = 0.03
L21_1.m_Talk_JPN = "\231\167\129\227\129\140\231\159\165\227\129\163\227\129\166\227\129\132\227\130\139<color=#ffd34c>\231\159\165\227\130\137\227\130\140\227\129\161\227\130\131\227\129\190\227\129\154\227\129\132\231\167\152\229\175\134</color>\227\130\146\227\129\138\229\174\162\230\167\152\227\130\130\231\159\165\227\129\163\227\129\166\227\129\138\227\129\132\227\129\159\227\129\187\227\129\134\227\129\140\227\129\132\227\129\132\227\129\168\230\128\157\227\129\132\227\129\190\227\129\151\227\129\166\227\128\130"
L21_1.m_Talk_ENG = "But I think you should know this <color=#ffd34c>uncomfortable truth</color> first."
L21_1.m_Talk_TWN = "\229\143\170\230\152\175\230\156\137\228\186\155<color=#ffd34c>\228\189\160\228\184\141\231\159\165\233\129\147\231\154\132\228\186\139</color>\239\188\140\228\189\160\233\130\132\230\152\175\231\159\165\233\129\147\228\184\128\228\184\139\230\175\148\232\188\131\229\165\189\227\128\130"
L21_1.m_Talk_THA = "\224\185\129\224\184\149\224\185\136\224\184\137\224\184\177\224\184\153\224\184\167\224\185\136\224\184\178\224\184\132\224\184\184\224\184\147\224\184\132\224\184\167\224\184\163\224\184\136\224\184\176\224\184\163\224\184\185\224\185\137<color=#ffd34c>\224\184\132\224\184\167\224\184\178\224\184\161\224\184\136\224\184\163\224\184\180\224\184\135\224\184\151\224\184\181\224\185\136\224\184\153\224\185\136\224\184\178\224\184\173\224\184\182\224\184\148\224\184\173\224\184\177\224\184\148</color>\224\184\153\224\184\181\224\185\137\224\184\129\224\185\136\224\184\173\224\184\153"
L21_1.m_Talk_VTN = "Nh\198\176ng t\195\180i ngh\196\169 c\195\180 n\195\170n bi\225\186\191t <color=#ffd34c>s\225\187\177 th\225\186\173t kh\195\179 ch\225\187\139u</color> n\195\160y tr\198\176\225\187\155c."
L21_1.m_Talk_SCN = "\228\184\141\232\191\135\230\136\145\232\167\137\229\190\151\233\161\190\229\174\162\229\165\189\229\131\143\228\185\159\229\186\148\232\175\165\228\186\134\232\167\163\228\184\128\228\184\139\230\136\145\230\137\128\231\159\165\233\129\147\231\154\132<color=#ffd34c>\229\136\171\230\137\173\231\154\132\231\167\152\229\175\134</color>\227\128\130"
L21_1.m_Talk_DEU = "Aber ich denke, du solltest zuerst diese <color=#ffd34c>unangenehme Wahrheit</color> kennen."
L21_1.m_Talk_FRA = "C'est juste que... Je crois que je devrais vous dire quelque chose. Une <color=#ffd34c>v\195\169rit\195\169 inavou\195\169e</color>..."
